def transform(grid):
    """Project interior markers along rows selected by matching side bars."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    def runs(values):
        result = []
        i = 0
        while i < len(values):
            j = i + 1
            while j < len(values) and values[j] == values[i]:
                j += 1
            if values[i] != bg and j - i >= 2:
                result.append((i, j - i, values[i]))
            i = j
        return result

    left_runs = runs([grid[r][0] for r in range(h)])
    right_runs = runs([grid[r][w - 1] for r in range(h)])
    out = [row[:] for row in grid]

    # Equal bars on opposite sides define corresponding row ranges.
    for left in left_runs:
        for right in right_runs:
            if left[1:] != right[1:]:
                continue
            lstart, length, _ = left
            rstart = right[0]
            for offset in range(length):
                r = rstart + offset
                # An interior colored mark on a right-bar row launches a
                # ray toward the right edge; its paired left-bar row is filled
                # across the grid in that mark's color.
                marks = [c for c in range(1, w - 1) if grid[r][c] != bg]
                for c in marks:
                    ink = grid[r][c]
                    out[r][c] = 4
                    for x in range(c + 1, w - 1):
                        if grid[r][x] == bg:
                            out[r][x] = ink
                        else:
                            break
                    paired_r = lstart + offset
                    for x in range(1, w):
                        if grid[paired_r][x] != bg:
                            break
                        out[paired_r][x] = ink
    return out

